// NewError converts a gRPC error into the ogen error response.
func (a *OgenAdapter) NewError(ctx context.Context, err error) *rest.ErrorStatusCode {
	st := grpcbridge.Status(err)
	e := rest.Error{}
	e.Code = st.Code().String()
	e.Details = grpcbridge.Details(st)
	e.Message = st.Message()
	return &rest.ErrorStatusCode{
		StatusCode: grpcbridge.HTTPStatus(st.Code()),
		Response:   e,
	}
}

